package id.dekat.booking.application;

import id.dekat.booking.domain.*;
import id.dekat.common.IdempotencyException;
import id.dekat.common.NotFoundException;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.OffsetDateTime;
import java.util.List;
import java.util.UUID;

@Service
@Transactional
public class BookingService {

private static final int HOLD_EXPIRY_MINUTES = 10;

private final BookingRepository bookingRepository;
    private final BookingHoldRepository bookingHoldRepository;

public BookingService(BookingRepository bookingRepository,
                          BookingHoldRepository bookingHoldRepository) {
        this.bookingRepository = bookingRepository;
        this.bookingHoldRepository = bookingHoldRepository;
    }

public BookingHold createHold(UUID tenantId, UUID locationId, UUID serviceId,
                                  UUID staffId, UUID resourceId, UUID customerId,
                                  OffsetDateTime startsAt, OffsetDateTime endsAt) {
        validateSlotAvailability(tenantId, staffId, startsAt, endsAt);
        BookingHold hold = new BookingHold(
                tenantId, locationId, serviceId, staffId, resourceId, customerId,
                startsAt, endsAt, OffsetDateTime.now().plusMinutes(HOLD_EXPIRY_MINUTES)
        );
        return bookingHoldRepository.save(hold);
    }

public Booking confirmBooking(UUID holdId, UUID tenantId, UUID locationId,
                                  UUID customerId, String currency, List<BookingItem> items) {
        BookingHold hold = bookingHoldRepository.findById(holdId)
                .orElseThrow(() -> new NotFoundException("Hold not found: " + holdId));

if (hold.getStatus() != BookingHold.HoldStatus.ACTIVE) {
            throw new IllegalStateException("Hold is no longer active: " + hold.getStatus());
        }
        if (hold.isExpired()) {
            hold.markExpired();
            throw new IllegalStateException("Hold has expired");
        }

Booking booking = new Booking(
                tenantId, locationId, customerId, generateBookingCode(),
                ServiceMode.AT_BUSINESS, hold.getStartsAt(), hold.getEndsAt(),
                java.time.ZoneId.of("Asia/Jakarta"), currency
        );
        booking.setItems(items);
        booking.recalculateTotal();
        booking.confirm();

hold.markConverted();
        bookingHoldRepository.save(hold);

return bookingRepository.save(booking);
    }

@Transactional
    public Booking rescheduleBooking(UUID bookingId, OffsetDateTime newStartsAt,
                                     OffsetDateTime newEndsAt, long expectedVersion) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));

if (!booking.getVersion().equals(expectedVersion)) {
            throw new IdempotencyException(
                "Booking has been modified. Expected version " + expectedVersion
                + " but found " + booking.getVersion()
            );
        }

validateSlotAvailability(booking.getTenantId(), null, newStartsAt, newEndsAt);
        booking.reschedule(newStartsAt, newEndsAt);
        return bookingRepository.save(booking);
    }

@Transactional
    public Booking cancelBooking(UUID bookingId, String reason, UUID actorId) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));
        booking.cancel();
        return bookingRepository.save(booking);
    }

public Booking checkIn(UUID bookingId, UUID actorId) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));
        booking.checkIn();
        return bookingRepository.save(booking);
    }

public Booking startService(UUID bookingId, UUID actorId) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));
        booking.startService();
        return bookingRepository.save(booking);
    }

public Booking completeService(UUID bookingId, UUID actorId) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));
        booking.complete();
        return bookingRepository.save(booking);
    }

public Booking recordNoShow(UUID bookingId, UUID actorId) {
        Booking booking = bookingRepository.findById(bookingId)
                .orElseThrow(() -> new NotFoundException("Booking not found: " + bookingId));
        booking.noShow();
        return bookingRepository.save(booking);
    }

public void validateSlotAvailability(UUID tenantId, UUID staffId,
                                         OffsetDateTime startsAt, OffsetDateTime endsAt) {
        List<Booking> overlaps;
        if (staffId != null) {
            overlaps = bookingRepository.findOverlappingBookingsForStaff(
                    tenantId, staffId, startsAt, endsAt
            );
        } else {
            overlaps = bookingRepository.findOverlappingBookings(tenantId, startsAt, endsAt);
        }
        if (!overlaps.isEmpty()) {
            throw new IllegalStateException("Time slot is not available: overlapping bookings exist");
        }

package id.dekat.booking.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Entity
@Table(name = "bookings")
public class Booking {

@Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

@Column(nullable = false)
    private UUID tenantId;

@Column(nullable = false)
    private UUID locationId;

@Column(nullable = false)
    private UUID customerId;

@Column(nullable = false, unique = true)
    private String bookingCode;

@Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private BookingStatus status;

@Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private ServiceMode serviceMode;

@Column(nullable = false)
    private OffsetDateTime startsAt;

private OffsetDateTime endsAt;

@Column(nullable = false)
    private ZoneId timezone;

@Column(nullable = false, length = 3)
    private String currency;

@Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal subtotal = BigDecimal.ZERO;

@Column(precision = 12, scale = 2)
    private BigDecimal discount = BigDecimal.ZERO;

@Column(precision = 12, scale = 2)
    private BigDecimal tax = BigDecimal.ZERO;

@Column(precision = 12, scale = 2)
    private BigDecimal fee = BigDecimal.ZERO;

@Column(precision = 12, scale = 2)
    private BigDecimal deposit = BigDecimal.ZERO;

@Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal total = BigDecimal.ZERO;

@Column(columnDefinition = "jsonb")
    @Convert(converter = id.dekat.common.JsonbMapConverter.class)
    private Map<String, Object> policySnapshot = new HashMap<>();

private String source;

private UUID campaignId;

private UUID referrerTenantId;

@Version
    private Long version;

@Column(nullable = false)
    private OffsetDateTime createdAt;

private OffsetDateTime confirmedAt;
    private OffsetDateTime completedAt;
    private OffsetDateTime cancelledAt;

@OneToMany(mappedBy = "bookingId", cascade = CascadeType.ALL, fetch = FetchType.LAZY)
    private List<BookingItem> items = new ArrayList<>();

@OneToMany(mappedBy = "bookingId", cascade = CascadeType.ALL, fetch = FetchType.LAZY)
    private List<BookingAssignment> assignments = new ArrayList<>();

protected Booking() {}

public Booking(UUID tenantId, UUID locationId, UUID customerId,
                   String bookingCode, ServiceMode serviceMode,
                   OffsetDateTime startsAt, OffsetDateTime endsAt,
                   ZoneId timezone, String currency) {
        this.tenantId = tenantId;
        this.locationId = locationId;
        this.customerId = customerId;
        this.bookingCode = bookingCode;
        this.status = BookingStatus.HELD;
        this.serviceMode = serviceMode;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.timezone = timezone;
        this.currency = currency;
        this.createdAt = OffsetDateTime.now();
    }

public void confirm() {
        if (this.status != BookingStatus.HELD && this.status != BookingStatus.PENDING_PAYMENT) {
            throw new IllegalStateException("Cannot confirm booking in status: " + this.status);
        }
        this.status = BookingStatus.CONFIRMED;
        this.confirmedAt = OffsetDateTime.now();
    }

public void cancel() {
        if (this.status == BookingStatus.COMPLETED || this.status == BookingStatus.CANCELLED) {
            throw new IllegalStateException("Cannot cancel booking in status: " + this.status);
        }
        this.status = BookingStatus.CANCELLED;
        this.cancelledAt = OffsetDateTime.now();
    }

public void checkIn() {
        if (this.status != BookingStatus.CONFIRMED) {
            throw new IllegalStateException("Cannot check in booking in status: " + this.status);
        }
        this.status = BookingStatus.CHECKED_IN;
    }

public void startService() {
        if (this.status != BookingStatus.CHECKED_IN && this.status != BookingStatus.EN_ROUTE) {
            throw new IllegalStateException("Cannot start service in status: " + this.status);
        }
        this.status = BookingStatus.IN_SERVICE;
    }

public void complete() {
        if (this.status != BookingStatus.IN_SERVICE) {
            throw new IllegalStateException("Cannot complete booking in status: " + this.status);
        }
        this.status = BookingStatus.COMPLETED;
        this.completedAt = OffsetDateTime.now();
    }

public void noShow() {
        if (this.status != BookingStatus.CONFIRMED && this.status != BookingStatus.CHECKED_IN) {
            throw new IllegalStateException("Cannot record no-show in status: " + this.status);
        }
        this.status = BookingStatus.NO_SHOW;
    }

public void reschedule(OffsetDateTime newStartsAt, OffsetDateTime newEndsAt) {
        if (this.status == BookingStatus.COMPLETED || this.status == BookingStatus.CANCELLED) {
            throw new IllegalStateException("Cannot reschedule booking in status: " + this.status);
        }
        this.startsAt = newStartsAt;
        this.endsAt = newEndsAt;
    }

public void recalculateTotal() {
        this.subtotal = items.stream()
                .map(BookingItem::lineTotal)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        this.total = subtotal.subtract(discount).add(tax).add(fee);
    }

public UUID getId() { return id; }
    public UUID getTenantId() { return tenantId; }
    public UUID getLocationId() { return locationId; }
    public UUID getCustomerId() { return customerId; }
    public String getBookingCode() { return bookingCode; }
    public BookingStatus getStatus() { return status; }
    public ServiceMode getServiceMode() { return serviceMode; }
    public OffsetDateTime getStartsAt() { return startsAt; }
    public OffsetDateTime getEndsAt() { return endsAt; }
    public ZoneId getTimezone() { return timezone; }
    public String getCurrency() { return currency; }
    public BigDecimal getSubtotal() { return subtotal; }
    public BigDecimal getDiscount() { return discount; }
    public BigDecimal getTax() { return tax; }
    public BigDecimal getFee() { return fee; }
    public BigDecimal getDeposit() { return deposit; }
    public BigDecimal getTotal() { return total; }
    public Map<String, Object> getPolicySnapshot() { return policySnapshot; }
    public String getSource() { return source; }
    public UUID getCampaignId() { return campaignId; }
    public UUID getReferrerTenantId() { return referrerTenantId; }
    public Long getVersion() { return version; }
    public OffsetDateTime getCreatedAt() { return createdAt; }
    public OffsetDateTime getConfirmedAt() { return confirmedAt; }
    public OffsetDateTime getCompletedAt() { return completedAt; }
    public OffsetDateTime getCancelledAt() { return cancelledAt; }
    public List<BookingItem> getItems() { return items; }
    public List<BookingAssignment> getAssignments() { return assignments; }

package id.dekat.booking.domain;

import jakarta.persistence.*;
import java.time.OffsetDateTime;
import java.util.UUID;

@Entity
@Table(name = "booking_assignments")
public class BookingAssignment {

public enum AssignmentStatus {
        ASSIGNED, CONFIRMED, DECLINED, COMPLETED, CANCELLED
    }

@Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

@Column(nullable = false)
    private UUID bookingId;

@Column(nullable = false)
    private UUID staffId;

private UUID resourceId;

@Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AssignmentStatus status;

private OffsetDateTime startsAt;
    private OffsetDateTime endsAt;

protected BookingAssignment() {}

public BookingAssignment(UUID bookingId, UUID staffId, UUID resourceId,
                             OffsetDateTime startsAt, OffsetDateTime endsAt) {
        this.bookingId = bookingId;
        this.staffId = staffId;
        this.resourceId = resourceId;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.status = AssignmentStatus.ASSIGNED;
    }

public void confirm() { this.status = AssignmentStatus.CONFIRMED; }
    public void decline() { this.status = AssignmentStatus.DECLINED; }
    public void complete() { this.status = AssignmentStatus.COMPLETED; }
    public void cancel() { this.status = AssignmentStatus.CANCELLED; }

public UUID getId() { return id; }
    public UUID getBookingId() { return bookingId; }
    public UUID getStaffId() { return staffId; }
    public UUID getResourceId() { return resourceId; }
    public AssignmentStatus getStatus() { return status; }
    public OffsetDateTime getStartsAt() { return startsAt; }
    public OffsetDateTime getEndsAt() { return endsAt; }
}

package id.dekat.booking.domain;

import jakarta.persistence.*;
import java.time.OffsetDateTime;
import java.util.UUID;

@Entity
@Table(name = "booking_holds")
public class BookingHold {

public enum HoldStatus {
        ACTIVE, EXPIRED, CONVERTED, CANCELLED
    }

@Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

@Column(nullable = false)
    private UUID tenantId;

@Column(nullable = false)
    private UUID locationId;

@Column(nullable = false)
    private UUID serviceId;

private UUID staffId;
    private UUID resourceId;
    private UUID customerId;

@Column(nullable = false)
    private OffsetDateTime startsAt;

@Column(nullable = false)
    private OffsetDateTime endsAt;

@Column(nullable = false)
    private OffsetDateTime expiresAt;

@Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private HoldStatus status;

protected BookingHold() {}

public BookingHold(UUID tenantId, UUID locationId, UUID serviceId,
                       UUID staffId, UUID resourceId, UUID customerId,
                       OffsetDateTime startsAt, OffsetDateTime endsAt,
                       OffsetDateTime expiresAt) {
        this.tenantId = tenantId;
        this.locationId = locationId;
        this.serviceId = serviceId;
        this.staffId = staffId;
        this.resourceId = resourceId;
        this.customerId = customerId;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.expiresAt = expiresAt;
        this.status = HoldStatus.ACTIVE;
    }

public boolean isExpired() {
        return OffsetDateTime.now().isAfter(expiresAt);
    }

public void markExpired() { this.status = HoldStatus.EXPIRED; }
    public void markConverted() { this.status = HoldStatus.CONVERTED; }
    public void markCancelled() { this.status = HoldStatus.CANCELLED; }

public UUID getId() { return id; }
    public UUID getTenantId() { return tenantId; }
    public UUID getLocationId() { return locationId; }
    public UUID getServiceId() { return serviceId; }
    public UUID getStaffId() { return staffId; }
    public UUID getResourceId() { return resourceId; }
    public UUID getCustomerId() { return customerId; }
    public OffsetDateTime getStartsAt() { return startsAt; }
    public OffsetDateTime getEndsAt() { return endsAt; }
    public OffsetDateTime getExpiresAt() { return expiresAt; }
    public HoldStatus getStatus() { return status; }
}

package id.dekat.booking.domain;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.OffsetDateTime;
import java.util.List;
import java.util.UUID;

@Repository
public interface BookingHoldRepository extends JpaRepository<BookingHold, UUID> {

List<BookingHold> findByStatus(BookingHold.HoldStatus status);

@Modifying
    @Query("""
        UPDATE BookingHold h SET h.status = id.dekat.booking.domain.BookingHold.HoldStatus.EXPIRED
        WHERE h.status = id.dekat.booking.domain.BookingHold.HoldStatus.ACTIVE
          AND h.expiresAt < :now
    """)
    int expireHolds(@Param("now") OffsetDateTime now);

@Query("""
        SELECT h FROM BookingHold h
        WHERE h.tenantId = :tenantId
          AND h.status = id.dekat.booking.domain.BookingHold.HoldStatus.ACTIVE
          AND h.startsAt < :endsAt
          AND h.endsAt > :startsAt
    """)
    List<BookingHold> findOverlappingHolds(
        @Param("tenantId") UUID tenantId,
        @Param("startsAt") OffsetDateTime startsAt,
        @Param("endsAt") OffsetDateTime endsAt
    );
}

package id.dekat.booking.domain;

import jakarta.persistence.*;
