package id.dekat.catalog.application;

import id.dekat.catalog.domain.*;
import id.dekat.catalog.web.dto.ServiceRequest;
import id.dekat.catalog.web.dto.ServiceResponse;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@Transactional
public class CatalogService {

private final ServiceRepository serviceRepository;
    private final CategoryRepository categoryRepository;

public CatalogService(ServiceRepository serviceRepository, CategoryRepository categoryRepository) {
        this.serviceRepository = serviceRepository;
        this.categoryRepository = categoryRepository;
    }

public ServiceItem createService(UUID tenantId, ServiceRequest request) {
        if (serviceRepository.existsBySlug(request.getSlug())) {
            throw new IllegalArgumentException("Slug already exists: " + request.getSlug());
        }

return serviceRepository.save(service);
    }

public ServiceItem updateService(UUID id, ServiceRequest request) {
        ServiceItem service = serviceRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + id));

public ServiceVariant createVariant(UUID serviceId, String name, BigDecimal priceAmount, Integer durationMinutes, String description) {
        serviceRepository.findById(serviceId)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + serviceId));

return ServiceVariant.builder()
                .serviceId(serviceId)
                .name(name)
                .priceAmount(priceAmount)
                .durationMinutes(durationMinutes)
                .description(description)
                .build();
    }

public ServiceAddon createAddon(UUID serviceId, String name, BigDecimal priceAmount, Integer durationMinutes, Integer maxQuantity, Boolean isRequired) {
        serviceRepository.findById(serviceId)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + serviceId));

return ServiceAddon.builder()
                .serviceId(serviceId)
                .name(name)
                .priceAmount(priceAmount)
                .durationMinutes(durationMinutes)
                .maxQuantity(maxQuantity)
                .isRequired(isRequired != null ? isRequired : false)
                .build();
    }

@Transactional(readOnly = true)
    public ServiceResponse getServiceWithPricing(UUID id) {
        ServiceItem service = serviceRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + id));
        return mapToResponse(service);
    }

@Transactional(readOnly = true)
    public List<ServiceResponse> getServicesByTenant(UUID tenantId) {
        return serviceRepository.findByTenantId(tenantId)
                .stream()
                .map(this::mapToResponse)
                .collect(Collectors.toList());
    }

public ServiceItem publishService(UUID id) {
        ServiceItem service = serviceRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + id));

ServiceItem updated = service.toBuilder()
                .status("ACTIVE")
                .visibility("PUBLIC")
                .build();

return serviceRepository.save(updated);
    }

public ServiceItem unpublishService(UUID id) {
        ServiceItem service = serviceRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Service not found: " + id));

