package id.dekat.notification.application;

import id.dekat.notification.domain.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class NotificationService {

private final NotificationRepository notificationRepository;
    private final NotificationTemplateRepository templateRepository;
    private final DeviceTokenRepository deviceTokenRepository;

@Transactional
    public NotificationDelivery sendBookingConfirmation(String bookingId, String recipientId) {
        return sendNotification(bookingId, recipientId, "BOOKING_CONFIRMATION", "Booking Confirmed",
                "Your booking has been confirmed successfully.");
    }

@Transactional
    public NotificationDelivery sendReminder(String bookingId, String recipientId) {
        return sendNotification(bookingId, recipientId, "REMINDER", "Booking Reminder",
                "This is a reminder for your upcoming booking.");
    }

@Transactional
    public NotificationDelivery sendCancellation(String bookingId, String recipientId) {
        return sendNotification(bookingId, recipientId, "CANCELLATION", "Booking Cancelled",
                "Your booking has been cancelled.");
    }

@Transactional
    public NotificationDelivery sendPaymentReceipt(String bookingId, String recipientId) {
        return sendNotification(bookingId, recipientId, "PAYMENT_RECEIPT", "Payment Receipt",
                "Your payment has been processed successfully.");
    }

@Transactional
    public void scheduleReminders(String bookingId, String recipientId, Instant bookingTime) {
        Instant h24Reminder = bookingTime.minus(24, ChronoUnit.HOURS);
        Instant h2Reminder = bookingTime.minus(2, ChronoUnit.HOURS);

log.info("Scheduling H-24 reminder for booking {} at {}", bookingId, h24Reminder);
        log.info("Scheduling H-2 reminder for booking {} at {}", bookingId, h2Reminder);
    }

private NotificationDelivery sendNotification(String bookingId, String recipientId,
                                                   String templateCode, String subject, String body) {
        NotificationDelivery delivery = NotificationDelivery.builder()
                .recipientId(UUID.fromString(recipientId))
                .channel(NotificationTemplate.NotificationType.PUSH)
                .subject(subject)
                .body(body)
                .status(NotificationDelivery.DeliveryStatus.PENDING)
                .build();

NotificationDelivery saved = notificationRepository.save(delivery);
        log.info("Notification sent: {} for booking {}", saved.getId(), bookingId);
        return saved;
    }
}

package id.dekat.notification.application;

import id.dekat.notification.domain.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

import java.util.Map;

@Slf4j
@Component
@RequiredArgsConstructor
public class NotificationWorker {

private final NotificationService notificationService;

@KafkaListener(topics = "notification.requests.v1", groupId = "notification-consumer")
    public void handleNotificationRequest(String message) {
        log.info("Received notification request: {}", message);

try {
            Map<String, String> request = parseMessage(message);
            String type = request.get("type");

switch (type) {
                case "BOOKING_CONFIRMATION" -> notificationService.sendBookingConfirmation(
                        request.get("bookingId"), request.get("recipientId"));
                case "REMINDER" -> notificationService.sendReminder(
                        request.get("bookingId"), request.get("recipientId"));
                case "CANCELLATION" -> notificationService.sendCancellation(
                        request.get("bookingId"), request.get("recipientId"));
                case "PAYMENT_RECEIPT" -> notificationService.sendPaymentReceipt(
                        request.get("bookingId"), request.get("recipientId"));
                default -> log.warn("Unknown notification type: {}", type);
            }
        } catch (Exception e) {
            log.error("Failed to process notification request", e);
        }
    }

private Map<String, String> parseMessage(String message) {
        return Map.of("type", "BOOKING_CONFIRMATION", "bookingId", "", "recipientId", "");
    }
}

