package id.dekat.scheduling.application;

import id.dekat.scheduling.domain.AvailabilityRule;
import id.dekat.scheduling.domain.AvailabilitySlot;
import id.dekat.scheduling.domain.SchedulingRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.*;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class AvailabilityService {

private final SchedulingRepository schedulingRepository;

@Transactional(readOnly = true)
    public List<AvailabilitySlot> getAvailableSlots(UUID tenantId, UUID staffId,
                                                     UUID resourceId, LocalDate date) {
        DayOfWeek dayOfWeek = date.getDayOfWeek();
        Instant dayStart = date.atStartOfDay(ZoneId.systemDefault()).toInstant();
        Instant dayEnd = date.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant();

List<AvailabilityRule> rules = schedulingRepository.findActiveRules(
                tenantId, staffId, dayOfWeek, dayStart);

List<AvailabilitySlot> slots = new ArrayList<>();
        for (AvailabilityRule rule : rules) {
            Instant slotStart = date.atTime(rule.getStartTime())
                    .atZone(ZoneId.systemDefault()).toInstant();
            Instant slotEnd = date.atTime(rule.getEndTime())
                    .atZone(ZoneId.systemDefault()).toInstant();

slots.add(AvailabilitySlot.builder()
                    .startsAt(slotStart)
                    .endsAt(slotEnd)
                    .staffId(staffId)
                    .resourceId(resourceId)
                    .available(true)
                    .build());
        }

return slots;
    }

@Transactional(readOnly = true)
    public boolean validateSlot(UUID tenantId, UUID staffId, Instant startsAt, Instant endsAt) {
        if (startsAt.isAfter(endsAt) || startsAt.equals(endsAt)) {
            return false;
        }

List<AvailabilityRule> rules = schedulingRepository.findByTenantIdAndStaffId(tenantId, staffId);
        for (AvailabilityRule rule : rules) {
            if (rule.getEffectiveFrom().isAfter(endsAt)) {
                continue;
            }
            if (rule.getEffectiveUntil() != null && rule.getEffectiveUntil().isBefore(startsAt)) {
                continue;
            }
            return true;
        }
        return false;
    }

@Transactional(readOnly = true)
    public List<AvailabilitySlot> getAvailableStaff(UUID tenantId, UUID resourceId, LocalDate date) {
        List<AvailabilityRule> rules = schedulingRepository.findByTenantIdAndDayOfWeekAndEffectiveFromLessThanEqualAndEffectiveUntilGreaterThanEqual(
                tenantId, date.getDayOfWeek(), date.atStartOfDay(ZoneId.systemDefault()).toInstant(),
                date.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant());

return rules.stream()
                .map(rule -> AvailabilitySlot.builder()
                        .startsAt(date.atTime(rule.getStartTime()).atZone(ZoneId.systemDefault()).toInstant())
                        .endsAt(date.atTime(rule.getEndTime()).atZone(ZoneId.systemDefault()).toInstant())
                        .staffId(rule.getStaffId())
                        .resourceId(rule.getResourceId())
                        .available(true)
                        .build())
                .collect(Collectors.toList());
    }

@Transactional(readOnly = true)
    public boolean checkOverlap(UUID tenantId, UUID staffId, Instant startsAt, Instant endsAt) {
        List<AvailabilityRule> rules = schedulingRepository.findByTenantIdAndStaffId(tenantId, staffId);
        for (AvailabilityRule rule : rules) {
            Instant ruleStart = rule.getEffectiveFrom();
            Instant ruleEnd = rule.getEffectiveUntil() != null ? rule.getEffectiveUntil() : Instant.MAX;
            if (startsAt.isBefore(ruleEnd) && endsAt.isAfter(ruleStart)) {
                return true;
            }
        }
        return false;
    }
}

