import java.util.List;
import java.util.UUID;

@Service
@Transactional
public class TenantService {

private final TenantRepository tenantRepository;
    private final LocationRepository locationRepository;

public TenantService(TenantRepository tenantRepository, LocationRepository locationRepository) {
        this.tenantRepository = tenantRepository;
        this.locationRepository = locationRepository;
    }

public Tenant createTenant(CreateTenantRequest request) {
        if (tenantRepository.existsBySlug(request.getSlug())) {
            throw new IllegalArgumentException("Slug already exists: " + request.getSlug());
        }

Tenant tenant = Tenant.builder()
                .name(request.getName())
                .slug(request.getSlug())
                .category(request.getCategory())
                .contactEmail(request.getContactEmail())
                .contactPhone(request.getContactPhone())
                .status(VerificationStatus.DRAFT)
                .build();

return tenantRepository.save(tenant);
    }

public Tenant updateTenant(UUID id, CreateTenantRequest request) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

Tenant updated = tenant.toBuilder()
                .name(request.getName())
                .slug(request.getSlug())
                .category(request.getCategory())
                .contactEmail(request.getContactEmail())
                .contactPhone(request.getContactPhone())
                .build();

return tenantRepository.save(updated);
    }

public Tenant submitForReview(UUID id) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

if (tenant.getStatus() != VerificationStatus.DRAFT) {
            throw new IllegalStateException("Only DRAFT tenants can be submitted for review");
        }

Tenant updated = tenant.toBuilder()
                .status(VerificationStatus.SUBMITTED)
                .build();

return tenantRepository.save(updated);
    }

public Tenant approveTenant(UUID id) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

if (tenant.getStatus() != VerificationStatus.UNDER_REVIEW) {
            throw new IllegalStateException("Only UNDER_REVIEW tenants can be approved");
        }

Tenant updated = tenant.toBuilder()
                .status(VerificationStatus.APPROVED)
                .build();

return tenantRepository.save(updated);
    }

public Tenant rejectTenant(UUID id) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

if (tenant.getStatus() != VerificationStatus.UNDER_REVIEW) {
            throw new IllegalStateException("Only UNDER_REVIEW tenants can be rejected");
        }

Tenant updated = tenant.toBuilder()
                .status(VerificationStatus.REJECTED)
                .build();

return tenantRepository.save(updated);
    }

public Tenant suspendTenant(UUID id) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

if (tenant.getStatus() != VerificationStatus.APPROVED) {
            throw new IllegalStateException("Only APPROVED tenants can be suspended");
        }

Tenant updated = tenant.toBuilder()
                .status(VerificationStatus.SUSPENDED)
                .build();

return tenantRepository.save(updated);
    }

public Tenant reactivateTenant(UUID id) {
        Tenant tenant = tenantRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found: " + id));

if (tenant.getStatus() != VerificationStatus.SUSPENDED) {
            throw new IllegalStateException("Only SUSPENDED tenants can be reactivated");
        }

Tenant updated = tenant.toBuilder()
                .status(VerificationStatus.APPROVED)
                .build();

return tenantRepository.save(updated);
    }

public Location createLocation(UUID tenantId, LocationRequest request) {
        if (!tenantRepository.existsById(tenantId)) {
            throw new IllegalArgumentException("Tenant not found: " + tenantId);
        }

Location updated = location.toBuilder()
                .name(request.getName())
                .address(request.getAddress())
                .latitude(request.getLatitude())
                .longitude(request.getLongitude())
                .timezone(request.getTimezone())
                .phone(request.getPhone())
                .serviceModes(request.getServiceModes())
                .operatingHours(request.getOperatingHours())
                .build();

return locationRepository.save(updated);
    }

@Transactional(readOnly = true)
    public Tenant getTenantBySlug(String slug) {
        return tenantRepository.findBySlug(slug)
                .orElseThrow(() -> new IllegalArgumentException("Tenant not found with slug: " + slug));
    }

